WITH parsed AS (SELECT id, effective_from, currency, tier_limits, tier_prices, discounts, ELEMENT_AT(tier_prices, 1) AS entry_price, AGGREGATE(tier_prices, CAST(0 AS DOUBLE), (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price FROM price_tiers WHERE currency = 'THB') SELECT currency, DATE_TRUNC('YEAR', effective_from) AS year_start, SIZE(COLLECT_SET(currency)) AS num_currencies, APPROX_PERCENTILE(avg_tier_price, 0.95) AS avg_tier_price_p95, PERCENTILE_APPROX(avg_tier_price, ARRAY(0.25, 0.5, 0.75)) AS avg_tier_price_quartiles, SUM(CASE WHEN currency = 'USD' THEN entry_price ELSE 0 END) AS usd_entry_price FROM parsed GROUP BY 1, 2;
